def score_phq9(row):
    items = [row.get(f'phq9_{i}') for i in range(1, 10)]
    # valid items: 0, 1, 2, 3
    valid_items = []
    skipped = 0
    for v in items:
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            skipped += 1
        else:
            valid_items.append(int(v))

    # self-harm flag: question 9
    q9 = row.get('phq9_9')
    if pd.isna(q9) or q9 not in [0, 1, 2, 3]:
        sh_flag = np.nan
    else:
        sh_flag = True if int(q9) in [1, 2, 3] else False

    if skipped >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif skipped == 1:
        # scale up: sum * 9 / 8, round half up
        s = sum(valid_items)
        scaled = (s * 9) / 8.0
        # half rounds up: 4.5 -> 5
        # python round() does round-to-even. Let's do exact half rounding up:
        total = int(np.floor(scaled + 0.5))
        prorated = True
    else:
        total = sum(valid_items)
        prorated = False

    # band
    if pd.isna(total):
        band = np.nan
    elif 0 <= total <= 4:
        band = 'none-minimal'
    elif 5 <= total <= 9:
        band = 'mild'
    elif 10 <= total <= 14:
        band = 'moderate'
    elif 15 <= total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    return total, band, prorated, sh_flag

