                    valid_items.append(iv)
            if skipped >= 2:
                tot = np.nan
            elif skipped == 1:
                tot = int(np.floor((sum(valid_items) * 10 / 9.0) + 0.5))
            else:
                tot = sum(valid_items)
            totals.append(tot)

        eq = (pd.Series(totals).astype(object).fillna('NA') == pipe['rses_total'].astype(object).fillna('NA')).sum()
